import {
  PaginationContent,
  PaginationItem,
  PaginationLink,
  Pagination,
} from "@/registry/erbium/ui/pagination";
import type * as React from "react";

const Example = (args: React.ComponentProps<typeof Pagination>) => (
  <Pagination {...args}>
    <PaginationContent>
      {[1, 2, 3].map((page) => (
        <PaginationItem key={page}>
          <PaginationLink href="#" isActive={page === 2}>
            {page}
          </PaginationLink>
        </PaginationItem>
      ))}
    </PaginationContent>
  </Pagination>
);

export default Example;
